() => {
  const selects = Array.from(document.querySelectorAll('select'));
  const sel = selects.find(s =>
    Array.from(s.options).some(o => o.value === 'countd_bntfje') &&
    Array.from(s.options).some(o => o.value === '')
  );
  if (!sel) return { error: 'sort select not found', selectCount: selects.length };
  const setter = Object.getOwnPropertyDescriptor(window.HTMLSelectElement.prototype, 'value').set;
  setter.call(sel, '');
  sel.dispatchEvent(new Event('change', { bubbles: true }));
  return { ok: true, domValueAfter: sel.value };
}

() => {
  const selects = Array.from(document.querySelectorAll('select'));
  const sel = selects.find(s => Array.from(s.options).some(o => o.value === 'countd_bntfje') || Array.from(s.options).some(o => o.textContent === '不排序'));
  const sql = Array.from(document.querySelectorAll('code')).map(c => c.textContent).join('\n---\n');
  const execBtn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('执行查询'));
  return {
    sortValue: sel ? sel.value : 'not found',
    sortText: sel ? sel.options[sel.selectedIndex]?.textContent : null,
    sql,
    execDisabled: execBtn ? execBtn.disabled : null,
  };
}

